INSERT INTO `seller_profiles` VALUES (11,22,'TechZone Komputery','techzone-komputery-techzone-sp-z-oo-22','Sklep komputerowy oferujący sprzedaż laptopów, komputerów stacjonarnych, podzespołów oraz akcesoriów komputerowych. Zapewniamy fachowe doradztwo, atrakcyjne ceny i szybką realizację zamówień.','logo-1785411658428.jpg',NULL,NULL,NULL,'8134567890','TechZone Sp. z o.o.',0,1,'2026-07-30 11:40:58','2026-07-30 11:40:58','ul. Informatyczna 15','Rzeszów','35-001'),(12,12,'PC Master','pc-master-pc-master-solutions-sp-z-oo-12','PC Master to sklep komputerowy specjalizujący się w sprzedaży komputerów gamingowych, laptopów, podzespołów oraz akcesoriów komputerowych. Pomagamy dobrać sprzęt dopasowany do potrzeb klientów — od pracy biurowej po profesjonalne zastosowania i gry.\r\n','logo-1785411716366.jpg',NULL,NULL,NULL,'6842739516','PC Master Solutions Sp. z o.o.',0,1,'2026-07-30 11:41:56','2026-07-30 11:41:56','ul. Elektronowa 12','Kraków','30-701'),(13,25,'CyberTech Store','cybertech-store-cybertech-solutions-michal-nowak-25','CyberTech Store oferuje nowoczesny sprzęt komputerowy, podzespoły PC, urządzenia gamingowe oraz akcesoria dla profesjonalistów i entuzjastów technologii. Stawiamy na wysoką jakość produktów, szybką wysyłkę i kompleksową obsługę klienta.\r\n',NULL,NULL,NULL,NULL,'7392846510','CyberTech Solutions Michał Nowak',0,1,'2026-07-30 11:42:43','2026-07-30 11:42:43','ul. Nowoczesna 24','Wrocław','50-120'),(14,36,'martynka patelnie ','martynka-patelnie-marrttyynka-36','martynka patelnie martynka patelnie martynka patelnie martynka patelnie martynka patelnie martynka patelnie ','logo-1785595825536.png',NULL,NULL,NULL,'1234567890','marrttyynka',0,1,'2026-08-01 14:50:25','2026-08-01 14:50:25','piastow 7','rzeszow','37-000');
